import { Module } from '@nestjs/common';
import { LoggerModule as PinoLoggerModule } from 'nestjs-pino';
import { randomUUID } from 'crypto';
import type { IncomingMessage, ServerResponse } from 'http';

/**
 * Structured logging — Pino over the default NestJS console logger.
 *
 *  - JSON output in production so log aggregators (Loki, CloudWatch,
 *    Datadog) can parse fields directly.
 *  - Pretty output in development for legibility.
 *  - Per-request correlation id: generated by the server,
 *    attached to every log line and echoed back on the response so
 *    a client can quote it when reporting bugs.
 *  - HTTP records allow only operational metadata. URLs, headers and error
 *    details can contain credentials under arbitrary names or encodings.
 */
@Module({
  imports: [
    PinoLoggerModule.forRoot({
      pinoHttp: {
        level: process.env.LOG_LEVEL || 'info',
        autoLogging: {
          ignore: (req: IncomingMessage) => {
            const url = req.url || '';
            return url === '/health' || url.startsWith('/health?');
          },
        },
        genReqId: (_req: IncomingMessage, res: ServerResponse) => {
          // A caller-controlled correlation ID can itself be a credential.
          const id = randomUUID();
          res.setHeader('X-Request-Id', id);
          return id;
        },
        serializers: {
          req: (req: { id: string; method: string }) => ({ id: req.id, method: req.method }),
          res: (res: { statusCode: number }) => ({ statusCode: res.statusCode }),
          // Axios/Prisma errors may carry headers, SQL parameters and secrets
          // in both their messages and stacks. Do not serialize that payload.
          err: () => ({ type: 'Error' }),
        },
        customProps: (req: IncomingMessage) => ({
          // Surface authenticated identity (set by passport / mcp-auth guards)
          userId: (req as any).user?.sub,
          orgId: (req as any).user?.organizationId,
          authMethod: (req as any).user?.authMethod,
        }),
        redact: {
          paths: [
            'req.headers.authorization',
            'req.headers.cookie',
            'req.headers["x-api-key"]',
            'req.headers["set-cookie"]',
            'res.headers["set-cookie"]',
            // Common DTO field names; class-validator's whitelist already
            // strips unknown fields, but redact in case a controller logs
            // its body.
            '*.password',
            '*.passwordHash',
            '*.token',
            '*.refreshToken',
            '*.accessToken',
            '*.apiKey',
            '*.secret',
          ],
          remove: true,
        },
        transport:
          process.env.NODE_ENV === 'production'
            ? undefined
            : {
                target: 'pino-pretty',
                options: {
                  singleLine: true,
                  colorize: true,
                  translateTime: 'SYS:HH:MM:ss.l',
                  ignore: 'pid,hostname,req,res,responseTime',
                },
              },
      },
    }),
  ],
  exports: [PinoLoggerModule],
})
export class AppLoggerModule {}
